       color: var(--muted);
       font-size: 0.95rem;
       margin: 0;
     }

     .status[data-state="success"] {
       color: #067647;
       font-weight: 600;
     }

     @media (max-width: 520px) {
       .page {
         padding: 1rem;
       }

       .card {
         border-radius: 20px;
       }

       .actions {
         align-items: stretch;
       }

       button {
         width: 100%;
       }
     }

     @media (forced-colors: active) {
       .card,
       input,
       button {
         forced-color-adjust: auto;
       }

       .skip-link {
         border: 1px solid CanvasText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main">Skip to main content</a>

   <div class="page">
     <main id="main">
       <section class="hero" aria-labelledby="page-title">
         <span class="eyebrow">Support</span>
         <h1 id="page-title">Contact our support team</h1>
         <p>Send a message and we’ll get back to you as soon as possible.</p>
       </section>

       <div class="card">
         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
             <input
               id="full-name"
               name="fullName"
               type="text"
               autocomplete="name"
               required
             >
             <p class="field-error" id="full-name-error" hidden>Error: Enter your full name.</p>
           </div>

           <div class="form-field">
             <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
             <input
               id="email-address"
               name="emailAddress"
               type="email"
               autocomplete="email"
               required
             >
             <p class="field-error" id="email-address-error" hidden>Error: Enter a valid email address.</p>
           </div>

           <div class="form-field">
             <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
             <input
               id="phone-number"
               name="phoneNumber"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-number-help"
             >
             <p class="field-help" id="phone-number-help">Use a format like +1 555 123 4567 or (555) 123-4567.</p>
             <p class="field-error" id="phone-number-error" hidden>Error: Enter a phone number in the expected format.</p>
           </div>

           <div class="actions">
             <button type="submit">Send message</button>
             <p class="status" id="form-status" role="status" aria-live="polite"></p>
           </div>
         </form>
       </div>
     </main>
   </div>

   <script>
     const form = document.getElementById('support-form');
     const status = document.getElementById('form-status');

     const fields = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate: (value) => value.trim().length > 0,
       },
       {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate: (value) => {
           if (!value.trim()) {
             return false;
           }

           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
         },
       },
       {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate: (value) => {
           const trimmed = value.trim();

           if (!trimmed) {
             return true;
           }

           return /^[+()]?[0-9\s().-]{7,}$/.test(trimmed);
         },
       },
     ];

     function setFieldState(field, isValid) {
       field.input.setAttribute('aria-invalid', String(!isValid));
       if (isValid) {
         field.input.removeAttribute('aria-errormessage');
       } else {
         field.input.setAttribute('aria-errormessage', field.error.id);
       }
       field.error.hidden = isValid;
     }

     function validateField(field) {
       const isValid = field.validate(field.input.value);
       setFieldState(field, isValid);
       return isValid;
     }

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const invalidField = fields.find((field) => !validateField(field));

       if (invalidField) {
         status.textContent = 'Please fix the highlighted fields and try again.';
         status.dataset.state = 'error';
         invalidField.input.focus();
         return;
       }

       status.textContent = 'Thanks — your message is ready to send.';
       status.dataset.state = 'success';
       form.reset();

       fields.forEach((field) => {
         field.input.removeAttribute('aria-invalid');
         field.input.removeAttribute('aria-errormessage');
         field.error.hidden = true;
       });
     });

     fields.forEach((field) => {
       field.input.addEventListener('input', () => {
         if (field.input.getAttribute('aria-invalid') === 'true') {
           validateField(field);
         }
       });
     });
   </script>
 </body>
 </html>

